import React, { useState } from "react";
import './wordle.css';
import Grid from './components/grid';
import Keyboard from "./components/keyboard";
import KeyboardListener from "../../keyboardlistener";

const DefaultWordle: React.FC = () => {
    const [keysPressed, setKeysPressed] = useState<string>('');
    const [number, addGuess] = useState(0);
    const [guesses, setGuess] = useState<string[]>(Array(6).fill('')); 

    const handleKeyPress = (key: string) => {
        setKeysPressed((prev) => {
            if (key === 'Backspace') {
                return prev.slice(0, -1);
            } else if (key === 'Enter') {
                if (prev.length === 5) {
                    setGuess((guessList) => {
                        const newGuessList = [...guessList];  // Copy array to avoid direct mutation
                        newGuessList[number] = prev;  // Use the latest value of keysPressed from the function argument
                        console.log(newGuessList[number]);
                        return newGuessList;
                    });
                    addGuess((prevNumber) => (prevNumber === 5 ? 0 : prevNumber + 1));
                }
                return prev;
            } else {
                if (prev.length < 5) {
                    return prev + key;
                } else {
                    console.log("Max word length reached");
                    return prev;
                }
            }
        });
        console.log({ keysPressed, number, guesses });
    };
    return(
        <>
            <div className="defaultwordlecontainer">
                <KeyboardListener onKeyPress={handleKeyPress} />
                <Grid word = {keysPressed} guessNumber={number} guesses = {guesses}/>
            </div>
        </>
    );
}

export default DefaultWordle;
